"""Record actual bounded source readings and exact retained source-parent scope."""
import hashlib,json,pathlib,subprocess,sys
ROOT=pathlib.Path(__file__).resolve().parents[1];BASE=ROOT/'research/v5/expansion/systems_source_followthrough'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_text(encoding='utf8'))
def put(p,d):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n',encoding='utf8')
def source_bytes(p):
 if p.startswith('/home/') and sys.platform=='win32':return subprocess.check_output(['wsl','--cd','/tmp','cat',p])
 return pathlib.Path(p).read_bytes()
SOURCES=[
 ('MUSL-TLS','musl1.2.5 static TLS implementation','https://musl.libc.org/releases/musl-1.2.5.tar.gz','Official musl1.2.5 archive','musl-1.2.5/src/env/__init_tls.c',[(1,153)],'Static template, per-thread vector, alignment, thread-pointer initialization and its failure boundary.'),
 ('MUSL-LOADER','musl1.2.5 loader and TLS publication','https://musl.libc.org/releases/musl-1.2.5.tar.gz','Official musl1.2.5 archive','musl-1.2.5/ldso/dynlink.c',[(1107,1259),(1410,1437),(1579,1647),(1649,1697),(1710,1792),(1799,2077)],'Selected library search/allocation, TLS reservation/publication, relocation, constructor and startup stages; no complete loader or libc audit.'),
 ('GLIBC-MAP','glibc2.43 selected segment mapper','https://packages.ubuntu.com/resolute-updates/glibc-source','Ubuntu glibc-source2.43-2ubuntu2.4','glibc-2.43/elf/dl-map-segments.h',[(1,232)],'File mappings, alignment reservation, inaccessible holes, partial-page zeroing and anonymous zero-fill.'),
 ('GLIBC-RELOC','glibc2.43 relocation owner','https://packages.ubuntu.com/resolute-updates/glibc-source','Ubuntu glibc-source2.43-2ubuntu2.4','glibc-2.43/elf/dl-reloc.c',[(205,348)],'Relocation owner, temporary protections, lazy/now selection and protection restoration; machine-specific macro bodies are separate.'),
 ('GLIBC-LOOKUP','glibc2.43 scoped lookup owner','https://packages.ubuntu.com/resolute-updates/glibc-source','Ubuntu glibc-source2.43-2ubuntu2.4','glibc-2.43/elf/dl-lookup.c',[(762,887)],'Scope traversal, unresolved weak/strong distinction, protected-symbol handling and dependency-retention handoff; lower do_lookup_x matcher not newly inspected.')]

def make_resources():
 rows=[];captures={};root='/home/frede/cmastery-startup-tools/source/'
 for short,title,url,edition,file,ranges,scope in SOURCES:
  path=root+file;data=source_bytes(path);lines=data.decode('utf8').splitlines();loc=[file+': lines'+str(lo)+'-'+str(hi) for lo,hi in ranges];captures[path]=hashlib.sha256(data).hexdigest()
  rows.append(dict(id='R-SYS-FOLLOW-'+short,title=title,authors=['musl maintainers' if short.startswith('MUSL') else 'GNU C Library maintainers'],edition=edition,year=None,kind='source',url=url,access='Actual local primary source passages read; package/archive provenance retained in legacy_systems_startup',domains=['T09','T10'],role='primary',reason=scope,prerequisites=['Original T07-T11 prerequisite contracts'],assignable=True,locators=loc,inspection=dict(date='2026-10-18',method='Direct UTF8 reads of exact cached primary source bodies',scope=scope,limits='Selected bodies only; no source-to-host-binary reproduction, whole-runtime correctness or physical observation.',source_path=path,source_sha256=captures[path],passage_sha256={l:hashlib.sha256(('\n'.join(lines[lo-1:hi])+'\n').encode()).hexdigest() for l,(lo,hi) in zip(loc,ranges)})))
 for short,title,url,edition,name,loc,scope in [
  ('HEX88','Intel Hexadecimal Object File Format Specification','https://kib.kiev.ua/x86docs/Intel/misc/INTELHEX.PDF','Revision A January6,1988; inspected11-page reprint bears1998 copyright','intelhex.pdf',['PDF/printed pages1-11: identity, all eight format sections and all six record types','Printed pages5 and7: record-layout figures visually rendered and inspected'],'Historical record syntax, distinct linear/segment address arithmetic and entry metadata; archive-hosted original document, not an Intel-hosted authenticity attestation.'),
  ('ELF43-DYNAMIC','ELF Object File Format dynamic linking','https://gabi.xinuos.com/elf/08-dynamic.html','4.3 DRAFT, moving primary page retrieved2026-10-18','dynamic.html',['Chapter8 sections8.1-8.6: interpreter, dynamic entries, dependencies, substitution, hash-table text, initialization/termination'],'Selected complete dynamic-linking chapter text; no new inspection of diagrams or all processor supplements, no relabeling as4.2 or original2001 gABI.')]:
  path='build/runtime-parent-sources/'+name;captures[path]=sha(ROOT/path)
  rows.append(dict(id='R-SYS-FOLLOW-'+short,title=title,authors=['Intel Corporation' if short=='HEX88' else 'Xinuos and ELF specification contributors'],edition=edition,year=1988 if short=='HEX88' else None,kind='specification',url=url,access='Actual complete named text read; HEX figures additionally inspected',domains=['T09'],role='primary',reason=scope,prerequisites=['Checked byte decoding and active C17 environment'],assignable=True,locators=loc,inspection=dict(date='2026-10-18',method='Primary web text plus private downloaded original; pypdf text and PyMuPDF images for HEX',scope=scope,limits='Document inspection is distinct from implementation conformance and publisher-hosted provenance.',capture=dict(path=path,sha256=captures[path]))))
 return dict(schema_version=1,resources=rows),captures

def main():
 resources,captures=make_resources();put(BASE/'resources.json',resources)
 assignments=[]
 for domain in ['T07','T08','T09','T10','T11']:
  for p in sorted((ROOT/'curriculum/v5/expansion/legacy_assessments').glob('PR-'+domain+'-*.json')):
   for c in read(p)['criteria']:
    tasks=[c['task'],*[v['task'] for v in c.get('variants',[])]]
    if any(any(word in task.lower() for word in ['loader','tls','compiler-rt','libgcc','retarget','dwarf','intel hex','debug companion']) for task in tasks):assignments.append(dict(path=p.relative_to(ROOT).as_posix(),id=c['id'],task=c['task'],variants=c.get('variants',[])))
 put(BASE/'assignment_scope.json',dict(schema_version=1,scope='All canonical T07-T11 criterion and delayed task texts searched for the actual named runtime/format obligations; broad gap prose is interpreted against these concrete contracts',assignments=assignments,conclusion='Tasks require bounded selected implementation contracts, explicit uninspected callees, one compiler-rt/libgcc helper and one concrete embedded output library; they do not require proving every implementation branch of entire libc/compiler libraries. No assigned missing body is closed by its function name.'))
 put(BASE/'inspection.json',dict(schema_version=1,external_source_sha256={p:h for p,h in captures.items() if p.startswith('/')},source_sha256={p:h for p,h in captures.items() if not p.startswith('/')},access_attempts=read(ROOT/'build/runtime-parent-sources/access.json'),successful_hex_download=dict(command='curl.exe --fail --location --max-time25 --output build/runtime-parent-sources/intelhex.pdf https://kib.kiev.ua/x86docs/Intel/misc/INTELHEX.PDF',exit_code=0,bytes=29218,sha256=captures['build/runtime-parent-sources/intelhex.pdf']),limits=['The first mirror was read through web text but its direct download returned403; the pinned11-page archive manifestation was then read separately.','No copyrighted source or book extract is committed.','No complete libc or complete current/historical ABI equivalence is inferred.']))
 put(BASE/'remaining_work.json',dict(schema_version=1,required=True,scope='Required source-derived companion preserving original T09 tasks',required_work=[dict(id='SE-SYS-HEX-01',required=True,title='Record semantics versus loader policy',objectives=['T09.10.c','T09.12.a','T09.12.b','T09.12.c'],families=['A','B','C','D','F','I'],shared_contract='labs/systems_source_followthrough/CONTRACTS.md',assessor_analysis='assessor/systems_source_followthrough/ANALYSIS.md',source_register=BASE.relative_to(ROOT).as_posix()+'/resources.json',source_ids=['R-SYS-FOLLOW-HEX88'],learner_artifacts=['labs/systems_source_followthrough/hex.h','labs/systems_source_followthrough/hex.c','labs/systems_source_followthrough/tests.c','labs/systems_source_followthrough/driver.c'],environment='Hosted ISO C17, first-principles byte parser; no actual loader/device writes',requirement='Implement every stated bounded profile, atomic rejection and window admission; independently explain the narrower policies',verification='tools/run_systems_source_followthrough.py and tools/check_systems_source_followthrough.py --self-test',variants=[dict(id='SE-SYS-HEX-01-DELAYED',minimum_days=7,task='Changed linear/segment wrap and nonwrapping device-window admission; exact task and separate assessor analysis in the shared contract')],validation_status='Source-bound campaign; no independent learner or external review')]))
 files=['resources.json','inspection.json','assignment_scope.json','comparison.md','remaining_work.json']
 put(BASE/'research_gate.json',dict(schema_version=1,status='passage-inspected',scope='Actual selected source readings and source-derived author companion, not independent content acceptance',resource_ids=[r['id'] for r in resources['resources']],research_input_sha256={(BASE/n).relative_to(ROOT).as_posix():sha(BASE/n) for n in files},limitations=['Exact published C17/C23 remain separately unavailable.','Archive-hosted HEX document is identified by bytes and imprint, not publisher authentication.','No whole-library correctness or current/historical ABI equivalence.']))
 print(json.dumps(dict(resources=len(resources['resources']),assigned_criteria=len(assignments))))
if __name__=='__main__':main()
